import { Component, OnInit } from '@angular/core';

interface MemoryCard {
  id: number;
  val: string;
  flipped: boolean;
  matched: boolean;
}

@Component({
  selector: 'app-memory-game',
  templateUrl: './memory-game.component.html',
  styleUrls: ['./memory-game.component.scss']
})
export class MemoryGameComponent implements OnInit {

  cards: MemoryCard[] = [];
  flippedCards: MemoryCard[] = [];
  moves = 0;
  matches = 0;
  isWon = false;

  private items = ['🍎', '🐱', '🚗', '⭐️', '📚', '🎈'];

  ngOnInit(): void {
    this.restartGame();
  }

  restartGame(): void {
    this.moves = 0;
    this.matches = 0;
    this.isWon = false;
    this.flippedCards = [];

    // ساخت جفت‌ها
    const pairs = [...this.items, ...this.items];
    const shuffled = pairs.sort(() => 0.5 - Math.random());

    this.cards = shuffled.map((val, idx) => ({
      id: idx,
      val,
      flipped: false,
      matched: false
    }));
  }

  onCardClick(card: MemoryCard): void {
    if (card.flipped || card.matched || this.flippedCards.length >= 2) {
      return;
    }

    card.flipped = true;
    this.flippedCards.push(card);

    if (this.flippedCards.length === 2) {
      this.moves++;
      this.checkMatch();
    }
  }

  private checkMatch(): void {
    const [c1, c2] = this.flippedCards;
    if (c1.val === c2.val) {
      c1.matched = true;
      c2.matched = true;
      this.matches++;
      this.flippedCards = [];
      if (this.matches === this.items.length) {
        this.isWon = true;
      }
    } else {
      setTimeout(() => {
        c1.flipped = false;
        c2.flipped = false;
        this.flippedCards = [];
      }, 900);
    }
  }
}
